[
  {
    "statement": "For controlling American bullfrogs in small ponds, direct removal methods are the most practical approaches.",
    "citations": []
  },
  {
    "statement": "Double fyke nets have been found effective for catching bullfrog tadpoles in small shallow ponds.",
    "citations": [
      "1046"
    ]
  },
  {
    "statement": "Bullfrog adults can be captured overnight in a single trap floating on the water surface.",
    "citations": [
      "1045"
    ]
  },
  {
    "statement": "The catchability of adult bullfrogs using one double fyke net for 24 hours was very low.",
    "citations": [
      "1045"
    ]
  },
  {
    "statement": "A before-and-after study in France showed a significant reduction in recorded adult and juvenile bullfrogs following the removal of juveniles by trapping when carried out as part of a combination treatment.",
    "citations": [
      "1046"
    ]
  },
  {
    "statement": "One replicated, controlled study found that bullfrog populations rapidly rebounded following intensive removal of adult bullfrogs.",
    "citations": [
      "1045"
    ]
  },
  {
    "statement": "Removal efforts for American bullfrogs need to be sustained.",
    "citations": [
      "1045"
    ]
  },
  {
    "statement": "No evidence was found for the effectiveness of pond draining or pond destruction methods.",
    "citations": [
      "1042",
      "1043"
    ]
  },
  {
    "statement": "No evidence was found for the cost-effectiveness of pond draining or pond destruction methods.",
    "citations": [
      "1042",
      "1043"
    ]
  }
]

[
  {
    "statement": "Removing food sources and draining waterways have been considered as control methods for Procambarus crayfish.",
    "citations": []
  },
  {
    "statement": "There is no captured evidence on the effect of either removing food sources or draining waterways to control Procambarus crayfish.",
    "citations": [
      "1033",
      "1034"
    ]
  },
  {
    "statement": "No evidence was captured on the effect of removing food sources as a control tool for Procambarus crayfish.",
    "citations": [
      "1033"
    ]
  },
  {
    "statement": "No evidence was captured on the effect of draining the waterway as a control tool for Procambarus crayfish.",
    "citations": [
      "1034"
    ]
  },
  {
    "statement": "The absence of evidence means that systematic journal and report searches have not yet found studies that directly and quantitatively tested these control methods.",
    "citations": []
  },
  {
    "statement": "The absence of evidence makes it impossible to assess the effectiveness of these control methods.",
    "citations": []
  },
  {
    "statement": "The absence of evidence makes it impossible to assess the potential harmful impacts of these control methods.",
    "citations": []
  }
]

[
  {
    "statement": "The evidence base specific to zebra mussel control using chemical biocides is limited.",
    "citations": []
  },
  {
    "statement": "No direct studies on zebra mussel control using chemical biocides were found in systematic searches.",
    "citations": []
  },
  {
    "statement": "Evidence from related invasive bivalve species suggests that chemical biocides can be effective.",
    "citations": []
  },
  {
    "statement": "Studies on Asian clams found that dosing with biocides including chlorine, potassium, and copper successfully killed these molluscs.",
    "citations": []
  },
  {
    "statement": "Higher concentrations of chlorine and bromine delivered at higher temperatures shortened the time required to achieve mortality in Asian clams.",
    "citations": []
  },
  {
    "statement": "A field-based trial in Spanish irrigation systems using fat-coated particles called BioBullets achieved 100% mortality of Asian clams within pipes.",
    "citations": []
  },
  {
    "statement": "The results from studies on other invasive bivalves demonstrate the potential effectiveness of chemical biocides for invasive bivalve control.",
    "citations": []
  },
  {
    "statement": "No studies were found that specifically evaluated the effectiveness of biocides for zebra mussels.",
    "citations": []
  },
  {
    "statement": "No studies were found that assessed the potential environmental impacts of biocides on non-target species.",
    "citations": []
  }
]

[
  {
    "statement": "The action documents reviewed provide limited information about the long-term impacts on native invertebrate communities after eradicating black bullheads using rotenone.",
    "citations": []
  },
  {
    "statement": "The documents primarily report the effectiveness of rotenone in eradicating black bullheads.",
    "citations": []
  },
  {
    "statement": "Studies in the UK and USA have demonstrated the successful eradication of black bullheads.",
    "citations": []
  },
  {
    "statement": "Documents concerning black bullhead eradication primarily focused on vertebrate species impacts.",
    "citations": []
  },
  {
    "statement": "Positive effects of the eradication on vertebrate species included increased amphibian species.",
    "citations": []
  },
  {
    "statement": "Positive effects of the eradication on vertebrate species included an increased abundance and recruitment of newt populations.",
    "citations": []
  },
  {
    "statement": "Negative effects of the eradication on vertebrate species included the death of many frogs.",
    "citations": []
  },
  {
    "statement": "A small number of newts showed symptoms of negative effects from the eradication.",
    "citations": []
  },
  {
    "statement": "No specific information about the long-term impacts on native invertebrate communities following black bullhead eradication using rotenone was found in the available action documents.",
    "citations": []
  }
]

[
  {
    "statement": "A replicated, controlled study in Belgium found that introducing northern pike led to a strong decline in bullfrog tadpole numbers.",
    "citations": [
      "1039"
    ]
  },
  {
    "statement": "One replicated, controlled study in the USA found that bullfrog populations rapidly rebounded following intensive removal of adults through direct capture methods.",
    "citations": [
      "1045"
    ]
  },
  {
    "statement": "One replicated study in Belgium found that catchability of adult bullfrogs using double fyke nets was very low.",
    "citations": [
      "1045"
    ]
  },
  {
    "statement": "One small study in the USA found that bullfrog adults can be captured overnight in a single floating trap.",
    "citations": [
      "1045"
    ]
  },
  {
    "statement": "A before-and-after study in France found a significant reduction in adult and juvenile numbers following the shooting of metamorphosed individuals before reproduction as part of a combination treatment.",
    "citations": [
      "1045"
    ]
  }
]

[
  {
    "statement": "There is currently no evidence available to assess the effectiveness of electrofishing for reducing Ponto-Caspian goby populations.",
    "citations": []
  },
  {
    "statement": "Electrofishing alone has been documented as a specific action for controlling Ponto-Caspian goby populations.",
    "citations": []
  },
  {
    "statement": "A combination of netting and electrofishing has been documented as a specific action for controlling Ponto-Caspian goby populations.",
    "citations": []
  },
  {
    "statement": "No studies were found that directly and quantitatively tested electrofishing alone as a control tool for invasive gobies.",
    "citations": []
  },
  {
    "statement": "No studies were found that directly and quantitatively tested a combination of netting and electrofishing as a control tool for invasive gobies.",
    "citations": []
  },
  {
    "statement": "The effectiveness of electrofishing, either alone or in combination with netting, remains unassessed due to a lack of scientific evidence.",
    "citations": []
  }
]

[
  {
    "statement": "Based on systematic searches of scientific literature, no evidence was found for the effectiveness of either draining invaded waterbodies or electrofishing for controlling brown and black bullheads.",
    "citations": []
  },
  {
    "statement": "No studies have been found that directly and quantitatively tested the methods of draining invaded waterbodies or electrofishing.",
    "citations": []
  },
  {
    "statement": "The lack of direct and quantitative studies makes it impossible to determine which approach between draining waterbodies and electrofishing is more effective.",
    "citations": []
  },
  {
    "statement": "The lack of evidence does not indicate that draining invaded waterbodies and electrofishing are ineffective methods.",
    "citations": []
  },
  {
    "statement": "The effectiveness of draining invaded waterbodies and electrofishing has not been scientifically assessed for brown and black bullhead control.",
    "citations": []
  }
]

[
  {
    "statement": "A systematic search of action documents captured no evidence regarding public perception of using sniffer dogs to control red-eared terrapin populations.",
    "citations": []
  },
  {
    "statement": "No studies have been found that examine public opinion, acceptance, or perception of using sniffer dogs for red-eared terrapin search and removal.",
    "citations": [
      "1058"
    ]
  },
  {
    "statement": "A public education action document shows no evidence was captured on the impact of education programs related to the use of sniffer dogs for red-eared terrapin control.",
    "citations": [
      "1060"
    ]
  },
  {
    "statement": "The lack of evidence means that systematic journal and report searches have not yet identified any studies that directly and quantitatively tested public perception of using sniffer dogs for red-eared terrapin control.",
